47		Content      string   `json:"content,omitempty" jsonschema:"New content/title for the task (optional)"`
48		Description  string   `json:"description,omitempty" jsonschema:"New description for the task (optional)"`
49		DueString    string   `json:"due_string,omitempty" jsonschema:"New due date in natural language (optional)"`
