91	// --- helpers ---
92	
93	func resolveTaskID(c *todoist.Client, id, name string) (string, string, error) {
94		if id != "" {
95			return id, "", nil
96		}
97		if name == "" {
98			return "", "", fmt.Errorf("either task_id or task_name is required")
99		}
100		task, err := c.FindTaskByName(name)
101		if err != nil {
102			return "", "", err
103		}
104		if task == nil {
105			return "", "", nil // not found
106		}
107		return task.ID, task.Content, nil
108	}
109	
110	func textResult(msg string, isError bool) *mcp.CallToolResult {
111		return &mcp.CallToolResult{
112			Content: []mcp.Content{&mcp.TextContent{Text: msg}},
113			IsError: isError,
114		}
115	}
116	
117	// --- registrations ---
118	
119	func registerTaskTools(s *mcp.Server, c *todoist.Client) {
120		mcp.AddTool(s, &mcp.Tool{
121			Name:        "todoist_create_task",
122			Description: "Create a new task in Todoist with optional description, due date, priority, project, section, labels, and assignee",
123		}, func(ctx context.Context, req *mcp.CallToolRequest, input CreateTaskInput) (*mcp.CallToolResult, CreateTaskOutput, error) {
124			body := map[string]any{"content": input.Content}
125			if input.Description != "" {
126				body["description"] = input.Description
127			}
128			if input.DueString != "" {
129				body["due_string"] = input.DueString
130			}
131			if input.Priority > 0 && input.Priority <= 4 {
132				body["priority"] = input.Priority
133			}
134			if input.ProjectID != "" {
135				body["project_id"] = input.ProjectID
136			}
137			if input.SectionID != "" {
138				body["section_id"] = input.SectionID
139			}
140			if input.ParentID != "" {
141				body["parent_id"] = input.ParentID
142			}
143			if len(input.Labels) > 0 {
144				body["labels"] = input.Labels
145			}
146			if input.AssigneeID != "" {
147				body["assignee_id"] = input.AssigneeID
148			}
149	
150			task, err := c.CreateTask(body)
151			if err != nil {
152				return nil, CreateTaskOutput{Success: false, Message: err.Error()}, err
153			}
154	
155			msg := fmt.Sprintf("Task created:\nTitle: %s", task.Content)
156			if task.Description != "" {
157				msg += fmt.Sprintf("\nDescription: %s", task.Description)
158			}
159			if task.Due != nil && task.Due.String != "" {
160				msg += fmt.Sprintf("\nDue: %s", task.Due.String)
161			}
162			if task.Priority > 0 {
163				msg += fmt.Sprintf("\nPriority: %d", task.Priority)
164			}
165	
166			return textResult(msg, false), CreateTaskOutput{Success: true, Message: msg}, nil
167		})
168	
169		mcp.AddTool(s, &mcp.Tool{
170			Name:        "todoist_get_tasks",
171			Description: "Get a list of tasks from Todoist with various filters",
172		}, func(ctx context.Context, req *mcp.CallToolRequest, input GetTasksInput) (*mcp.CallToolResult, GetTasksOutput, error) {
173			var tasks []models.Task
174			var err error
175			if input.Filter != "" {
176				tasks, err = c.GetTasksByFilter(input.Filter)
177			} else {
178				tasks, err = c.GetTasks(input.ProjectID)
179			}
180			if err != nil {
181				return nil, GetTasksOutput{}, err
182			}
183	
184			// Apply priority filter.
185			if input.Priority > 0 && input.Priority <= 4 {
186				filtered := tasks[:0]
187				for _, t := range tasks {
188					if t.Priority == input.Priority {
189						filtered = append(filtered, t)
190					}
191				}
192				tasks = filtered
193			}
194	
195			// Apply limit.
196			limit := input.Limit
197			if limit == 0 {
198				limit = 10
199			}
200			if len(tasks) > limit {
201				tasks = tasks[:limit]
202			}
203	
204			var msg string
205			if len(tasks) == 0 {
206				msg = "No tasks found matching the criteria"
207			} else {
208				var lines []string
209				for _, t := range tasks {
210					s := fmt.Sprintf("- %s (ID: %s)", t.Content, t.ID)
211					if t.Description != "" {
212						s += fmt.Sprintf("\n  Description: %s", t.Description)
213					}
214					if t.Due != nil && t.Due.String != "" {
215						s += fmt.Sprintf("\n  Due: %s", t.Due.String)
216					}
217					if t.Priority > 0 {
218						s += fmt.Sprintf("\n  Priority: %d", t.Priority)
219					}
220					lines = append(lines, s)
221				}
222				msg = strings.Join(lines, "\n\n")
223			}
224	
225			return textResult(msg, false), GetTasksOutput{Success: true, Message: msg}, nil
226		})
227	
228		mcp.AddTool(s, &mcp.Tool{
229			Name:        "todoist_update_task",
230			Description: "Update an existing task in Todoist by task_id or by searching by name",
231		}, func(ctx context.Context, req *mcp.CallToolRequest, input UpdateTaskInput) (*mcp.CallToolResult, UpdateTaskOutput, error) {
232			id, originalName, err := resolveTaskID(c, input.TaskID, input.TaskName)
233			if err != nil {
234				return nil, UpdateTaskOutput{Success: false, Message: err.Error()}, err
235			}
236			if id == "" {
237				msg := fmt.Sprintf("Could not find a task matching \"%s\"", input.TaskName)
238				return textResult(msg, true), UpdateTaskOutput{Success: false, Message: msg}, nil
239			}
240	
241			body := map[string]any{}
242			if input.Content != "" {
243				body["content"] = input.Content
244			}
245			if input.Description != "" {
246				body["description"] = input.Description
247			}
248			if input.DueString != "" {
249				body["due_string"] = input.DueString
250			}
251			if input.Priority > 0 && input.Priority <= 4 {
252				body["priority"] = input.Priority
253			}
254			if len(input.Labels) > 0 {
255				body["labels"] = input.Labels
256			}
257			if input.AssigneeID != "" {
258				body["assignee_id"] = input.AssigneeID
259			}
260			if input.DeadlineDate != "" {
261				body["deadline_date"] = input.DeadlineDate
262			}
263	
264			updated, err := c.UpdateTask(id, body)
265			if err != nil {
266				return nil, UpdateTaskOutput{Success: false, Message: err.Error()}, err
267			}
268	
269			label := originalName
270			if label == "" {
271				label = id
272			}
273			msg := fmt.Sprintf("Task \"%s\" updated:\nNew Title: %s", label, updated.Content)
274			if updated.Description != "" {
275				msg += fmt.Sprintf("\nNew Description: %s", updated.Description)
276			}
277			if updated.Due != nil && updated.Due.String != "" {
278				msg += fmt.Sprintf("\nNew Due Date: %s", updated.Due.String)
279			}
280			if updated.Priority > 0 {
281				msg += fmt.Sprintf("\nNew Priority: %d", updated.Priority)
282			}
283	
284			return textResult(msg, false), UpdateTaskOutput{Success: true, Message: msg}, nil
285		})
286	
287		mcp.AddTool(s, &mcp.Tool{
288			Name:        "todoist_delete_task",
289			Description: "Delete a task from Todoist by task_id or by searching by name",
290		}, func(ctx context.Context, req *mcp.CallToolRequest, input DeleteTaskInput) (*mcp.CallToolResult, DeleteTaskOutput, error) {
291			id, originalName, err := resolveTaskID(c, input.TaskID, input.TaskName)
292			if err != nil {
293				return nil, DeleteTaskOutput{Success: false, Message: err.Error()}, err
294			}
295			if id == "" {
